with RecentDepartments as (select * from departments where location in ('London', 'Singapore') or location = 'Singapore'), dept_name_group_summary as (select case when dept_name in ('Marketing', 'Finance') then 'priority' else 'other' end as dept_name_group, dept_name, sum(budget) as total_budget from RecentDepartments group by case when dept_name in ('Marketing', 'Finance') then 'priority' else 'other' end, dept_name) select * from dept_name_group_summary order by 2;
